%[text] # Test and coverage summary report
%[text] This script generates tables containing test summary and code coverage information. This script requires the `test-result.xml` and `code-coverage.xml` files that were genearted by the Build Tool.
disp("UTC " + string(datetime("now", TimeZone="UTC", Format="yyyy-MM-dd HH:mm:ss"))) %[output:48631d85]
disp(matlabRelease) %[output:6b1b054c]
% current_folder = extractAfter(pwd, asManyOfPattern(wildcardPattern + ("/"|"\")));
current_folder = pwd;

% Check that the "test-result" folder exists.
assert(isfolder("test-result"))

% Check that the "test-result.xml" file exists in the "tes-result" folder.
test_result_filename = "test-result.xml";
test_result_file_fullpath = fullfile(current_folder, "test-result", test_result_filename);
if not(isfile(test_result_file_fullpath))
  % The buildtool can find this script and run after having removed the test-result.xml file.
  disp(test_result_filename + " was not found.")

  return

end  % if

% Check that the "code-coverage.xml" file exists in the "tes-result" folder.
code_coverage_filename = "code-coverage.xml";
code_coverage_file_fullpath = fullfile(current_folder, "test-result", code_coverage_filename);
if not(isfile(code_coverage_file_fullpath))
  % The buildtool can find this script and run after having removed the code-coverage.xml file.
  disp(code_coverage_filename + " was not found.")

  return

end  % if

addpath("TestUtil")
test_summary_table = TestUtil1.summarizeTestResult(test_result_file_fullpath);
code_coverage_summary_struct = TestUtil1.summarizeCodeCoverage(code_coverage_file_fullpath);
rmpath("TestUtil")

disp("Test top folder: " + code_coverage_summary_struct.TotalCoverage.Properties.CustomProperties.TopFolder) %[output:38a12db2]

disp(test_summary_table.Properties.CustomProperties) %[output:2c157886]
disp("Slow tests:") %[output:05adb06f]
disp(head(test_summary_table, min(50, height(test_summary_table)))) %[output:4a6b3777]

disp(code_coverage_summary_struct.TotalCoverage) %[output:3011ed21]
disp(code_coverage_summary_struct.ComponentCoverage) %[output:924f8a59]
disp("Low-coverage code files:") %[output:8432f593]
disp(head(code_coverage_summary_struct.FileCoverage, min(50, height(code_coverage_summary_struct.FileCoverage)))) %[output:9ecbdf7b]
